package com.crms.entity;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;@Document("companies") public class Company{@Id private Long id;private User owner;private String name,description,website,industry;public Long getId(){return id;}public void setId(Long v){id=v;}public User getOwner(){return owner;}public void setOwner(User v){owner=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getWebsite(){return website;}public void setWebsite(String v){website=v;}public String getIndustry(){return industry;}public void setIndustry(String v){industry=v;}}
